const isEmojiCode = (str: string, pos: number): boolean => {
    const leftString = str.slice(0, pos);
    const colonIndex = leftString.lastIndexOf(':');

    // No colon found, cannot be an emoji code
    if (colonIndex < 0) {
        return false;
